728	    assert(Token.getType()->isTokenTy());
729	    auto &Regs = *VMap.getVRegs(Token);
730	    if (!Regs.empty()) {
731	      assert(Regs.size() == 1 &&
732	             "Expected a single register for convergence tokens.");
733	      return Regs[0];
