157	bool InstructionSelect::selectMachineFunction(MachineFunction &MF) {
158	  LLVM_DEBUG(dbgs() << "Selecting function: " << MF.getName() << '\n');
159	  assert(ISel && "Cannot work without InstructionSelector");
160	
161	  CodeGenCoverage CoverageInfo;
162	  ISel->setupMF(MF, VT, &CoverageInfo, PSI, BFI);
163	
164	  // An optimization remark emitter. Used to report failures.
165	  MachineOptimizationRemarkEmitter MORE(MF, /*MBFI=*/nullptr);
166	  ISel->MORE = &MORE;
167	
168	  // FIXME: There are many other MF/MFI fields we need to initialize.
169	
170	  MachineRegisterInfo &MRI = MF.getRegInfo();
171	#ifndef NDEBUG
172	  // Check that our input is fully legal: we require the function to have the
173	  // Legalized property, so it should be.
174	  // FIXME: This should be in the MachineVerifier, as the RegBankSelected
175	  // property check already is.
176	  if (!DisableGISelLegalityCheck)
177	    if (const MachineInstr *MI = machineFunctionIsIllegal(MF)) {
178	      reportGISelFailure(MF, MORE, "gisel-select", "instruction is not legal",
179	                         *MI);
180	      return false;
181	    }
182	  // NumBlocks is an invariant to ensure the number of blocks doesn't change.
183	  const size_t NumBlocks = MF.size();
184	#endif
185	  // Keep track of selected blocks, so we can delete unreachable ones later.
186	  DenseSet<MachineBasicBlock *> SelectedBlocks;
187	
188	  {
189	    // Observe IR insertions and removals during selection.
190	    // We only install a MachineFunction::Delegate instead of a
191	    // GISelChangeObserver, because we do not want notifications about changed
192	    // instructions. This prevents significant compile-time regressions from
193	    // e.g. constrainOperandRegClass().
194	    GISelObserverWrapper AllObservers;
195	    MIIteratorMaintainer MIIMaintainer;
196	    AllObservers.addObserver(&MIIMaintainer);
197	    RAIIDelegateInstaller DelInstaller(MF, &AllObservers);
198	    ISel->AllObservers = &AllObservers;
199	
200	    for (MachineBasicBlock *MBB : post_order(&MF)) {
201	      ISel->CurMBB = MBB;
202	      SelectedBlocks.insert(MBB);
203	
204	      // Select instructions in reverse block order.
205	      MIIMaintainer.MII = MBB->rbegin();
206	      for (auto End = MBB->rend(); MIIMaintainer.MII != End;) {
207	        MachineInstr &MI = *MIIMaintainer.MII;
208	        // Increment early to skip instructions inserted by select().
209	        ++MIIMaintainer.MII;
210	
211	        LLVM_DEBUG(dbgs() << "\nSelect:  " << MI);
212	        if (!selectInstr(MI)) {
213	          LLVM_DEBUG(dbgs() << "Selection failed!\n";
214	                     MIIMaintainer.reportFullyCreatedInstrs());
215	          reportGISelFailure(MF, MORE, "gisel-select", "cannot select", MI);
216	          return false;
217	        }
218	        LLVM_DEBUG(MIIMaintainer.reportFullyCreatedInstrs());
219	      }
220	    }
221	  }
222	
223	  for (MachineBasicBlock &MBB : MF) {
224	    if (MBB.empty())
225	      continue;
226	
227	    if (!SelectedBlocks.contains(&MBB)) {
228	      // This is an unreachable block and therefore hasn't been selected, since
229	      // the main selection loop above uses a postorder block traversal.
230	      // We delete all the instructions in this block since it's unreachable.
231	      MBB.clear();
232	      // Don't delete the block in case the block has it's address taken or is
233	      // still being referenced by a phi somewhere.
234	      continue;
235	    }
236	    // Try to find redundant copies b/w vregs of the same register class.
237	    for (auto MII = MBB.rbegin(), End = MBB.rend(); MII != End;) {
238	      MachineInstr &MI = *MII;
239	      ++MII;
240	
241	      if (MI.getOpcode() != TargetOpcode::COPY)
242	        continue;
243	      Register SrcReg = MI.getOperand(1).getReg();
244	      Register DstReg = MI.getOperand(0).getReg();
245	      unsigned SrcSubIdx = MI.getOperand(1).getSubReg();
246	      if (!SrcReg.isVirtual() || !DstReg.isVirtual() || SrcSubIdx)
247	        continue;
248	
249	      const TargetRegisterClass *SrcRC = MRI.getRegClass(SrcReg);
250	      const TargetRegisterClass *DstRC = MRI.getRegClass(DstReg);
251	      if (SrcRC == DstRC) {
252	        MRI.replaceRegWith(DstReg, SrcReg);
253	        MI.eraseFromParent();
254	      }
255	    }
256	  }
257	
258	#ifndef NDEBUG
259	  const TargetRegisterInfo &TRI = *MF.getSubtarget().getRegisterInfo();
260	  // Now that selection is complete, there are no more generic vregs.  Verify
261	  // that the size of the now-constrained vreg is unchanged and that it has a
262	  // register class.
263	  for (unsigned I = 0, E = MRI.getNumVirtRegs(); I != E; ++I) {
264	    Register VReg = Register::index2VirtReg(I);
265	
266	    MachineInstr *MI = nullptr;
267	    if (!MRI.def_empty(VReg))
268	      MI = &*MRI.def_instr_begin(VReg);
269	    else if (!MRI.use_empty(VReg)) {
270	      MI = &*MRI.use_instr_begin(VReg);
271	      // Debug value instruction is permitted to use undefined vregs.
272	      if (MI->isDebugValue())
273	        continue;
274	    }
275	    if (!MI)
276	      continue;
277	
278	    const TargetRegisterClass *RC = MRI.getRegClassOrNull(VReg);
279	    if (!RC) {
280	      reportGISelFailure(MF, MORE, "gisel-select",
281	                         "VReg has no regclass after selection", *MI);
282	      return false;
283	    }
284	
285	    const LLT Ty = MRI.getType(VReg);
286	    if (Ty.isValid() &&
287	        TypeSize::isKnownGT(Ty.getSizeInBits(), TRI.getRegSizeInBits(*RC))) {
288	      reportGISelFailure(
289	          MF, MORE, "gisel-select",
290	          "VReg's low-level type and register class have different sizes", *MI);
291	      return false;
292	    }
293	  }
294	
295	  if (MF.size() != NumBlocks) {
296	    MachineOptimizationRemarkMissed R("gisel-select", "GISelFailure",
297	                                      MF.getFunction().getSubprogram(),
298	                                      /*MBB=*/nullptr);
299	    R << "inserting blocks is not supported yet";
300	    reportGISelFailure(MF, MORE, R);
301	    return false;
302	  }
303	#endif
304	
305	  if (!DebugCounter::shouldExecute(GlobalISelCounter)) {
306	    dbgs() << "Falling back for function " << MF.getName() << "\n";
307	    MF.getProperties().setFailedISel();
308	    return false;
309	  }
310	
311	  // Determine if there are any calls in this machine function. Ported from
312	  // SelectionDAG.
313	  MachineFrameInfo &MFI = MF.getFrameInfo();
314	  for (const auto &MBB : MF) {
315	    if (MFI.hasCalls() && MF.hasInlineAsm())
316	      break;
317	
318	    for (const auto &MI : MBB) {
319	      if ((MI.isCall() && !MI.isReturn()) || MI.isStackAligningInlineAsm())
320	        MFI.setHasCalls(true);
321	      if (MI.isInlineAsm())
322	        MF.setHasInlineAsm(true);
323	    }
324	  }
325	
326	  // FIXME: FinalizeISel pass calls finalizeLowering, so it's called twice.
327	  auto &TLI = *MF.getSubtarget().getTargetLowering();
328	  TLI.finalizeLowering(MF);
329	
330	  LLVM_DEBUG({
331	    dbgs() << "Rules covered by selecting function: " << MF.getName() << ":";
332	    for (auto RuleID : CoverageInfo.covered())
333	      dbgs() << " id" << RuleID;
334	    dbgs() << "\n\n";
335	  });
336	  CoverageInfo.emit(CoveragePrefix,
337	                    TLI.getTargetMachine().getTarget().getBackendName());
338	
339	  // If we successfully selected the function nothing is going to use the vreg
340	  // types after us (otherwise MIRPrinter would need them). Make sure the types
341	  // disappear.
342	  MRI.clearVirtRegTypes();
343	
344	  // FIXME: Should we accurately track changes?
345	  return true;
346	}
347	
348	bool InstructionSelect::selectInstr(MachineInstr &MI) {
349	  MachineRegisterInfo &MRI = ISel->MF->getRegInfo();
350	
351	  // We could have folded this instruction away already, making it dead.
352	  // If so, erase it.
353	  if (isTriviallyDead(MI, MRI)) {
354	    LLVM_DEBUG(dbgs() << "Is dead.\n");
355	    salvageDebugInfo(MRI, MI);
356	    MI.eraseFromParent();
357	    return true;
358	  }
359	
360	  // Eliminate hints or G_CONSTANT_FOLD_BARRIER.
361	  if (isPreISelGenericOptimizationHint(MI.getOpcode()) ||
362	      MI.getOpcode() == TargetOpcode::G_CONSTANT_FOLD_BARRIER) {
363	    auto [DstReg, SrcReg] = MI.getFirst2Regs();
364	
365	    // At this point, the destination register class of the op may have
366	    // been decided.
367	    //
368	    // Propagate that through to the source register.
369	    const TargetRegisterClass *DstRC = MRI.getRegClassOrNull(DstReg);
370	    const TargetRegisterClass *SrcRC = MRI.getRegClassOrNull(SrcReg);
371	    if (DstRC && SrcRC)
372	      MRI.constrainRegClass(SrcReg, DstRC);
373	    else if (DstRC)
374	      MRI.setRegClass(SrcReg, DstRC);
375	    MI.eraseFromParent();
376	    MRI.replaceRegWith(DstReg, SrcReg);
377	    return true;
378	  }
379	
380	  if (MI.getOpcode() == TargetOpcode::G_INVOKE_REGION_START) {
381	    MI.eraseFromParent();
382	    return true;
383	  }
384	
385	  return ISel->select(MI);
386	}
